Extract the incident deployment manifest from the user text as a single raw JSON object strictly conforming to the JSON Schema below. Do not include Markdown fences, comments, or prose outside the JSON.

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "IncidentDeploymentManifest",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "incident_id",
    "severity",
    "rollback_required",
    "affected_services",
    "remediation_steps",
    "approvals"
  ],
  "properties": {
    "incident_id": {
      "type": "string",
      "pattern": "^INC-[0-9]{4}$",
      "description": "Incident identifier matching INC-XXXX."
    },
    "severity": {
      "type": "string",
      "enum": [
        "SEV1",
        "SEV2",
        "SEV3"
      ],
      "description": "Incident severity level."
    },
    "rollback_required": {
      "type": "boolean",
      "description": "Whether an immediate deployment rollback is required."
    },
    "affected_services": {
      "type": "array",
      "minItems": 2,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "service_name",
          "region",
          "replicas",
          "error_rate_pct",
          "owner_note"
        ],
        "properties": {
          "service_name": {
            "type": "string",
            "description": "Lowercase hyphenated service name."
          },
          "region": {
            "type": "string",
            "enum": [
              "us-east",
              "us-west",
              "eu-central",
              "ap-south"
            ]
          },
          "replicas": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "desired",
              "healthy"
            ],
            "properties": {
              "desired": {
                "type": "integer",
                "minimum": 1
              },
              "healthy": {
                "type": "integer",
                "minimum": 0
              }
            }
          },
          "error_rate_pct": {
            "type": "number",
            "minimum": 0,
            "maximum": 100
          },
          "owner_note": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "description": "Explicit owner note if given, otherwise null."
          }
        }
      }
    },
    "remediation_steps": {
      "type": "array",
      "minItems": 2,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "step_order",
          "action_type",
          "target_service",
          "timeout_seconds"
        ],
        "properties": {
          "step_order": {
            "type": "integer",
            "minimum": 1
          },
          "action_type": {
            "type": "string",
            "enum": [
              "drain",
              "rollback",
              "scale",
              "patch"
            ]
          },
          "target_service": {
            "type": "string"
          },
          "timeout_seconds": {
            "type": "integer",
            "minimum": 10
          }
        }
      }
    },
    "approvals": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "primary_approver",
        "secondary_approver"
      ],
      "properties": {
        "primary_approver": {
          "type": "string"
        },
        "secondary_approver": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Secondary approver name if mentioned, otherwise null."
        }
      }
    }
  }
}

